INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('enfekthyte','Enfekthyte','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"enfekthyte","name":"Enfekthyte","team":"demon","ability":"Each night*, choose a player: they die. If a marked executes & kills a good, they become evil & swap characters with you (once).","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-610 is an incurable skin disease that transmogrifies the diseased into blobs of flesh that do nothing but consume and roam aimlessly.","summaryBullets":["On the script, there can be any amount of characters that marked with the Enfekthyte''s character icon to indicate they are susceptible to infected.","Should any player with a marked character be the nominator & executor of another good player, they will become infected with the emotions of evil and swap characters with the Demon.","This fails should the executee not suffer a death.","This does not regard if the currently marked player started as a different character before this, or is a different character but has a marked character''s ability; that player simply must be the specified character in the roster of marks.","After the swap, new Enfekthyte learns they are the Demon immediately, as the old Enfekthyte learns what character they swapped with."],"howToRun":["On the script, place a mark on characters you want to be susceptible to the spread of hate.","Each night except the first, wake the Enfekthyte. They point at any player. That player {{i|dies}} - mark them with the **DEAD** reminder. Put the the Enfekthyte to sleep.","If a player with a marked character nominates the good player, that nomination results in their execution & death, and the **INFECTED** reminder token isn''t present, immediately swap the character tokens of the chosen players. That night, one at a time, wake each swapped player, show them the **YOU ARE** info token and their new character token, then also show the new Enfekthyte the **YOU ARE** info token then give a thumbs down. Put them to sleep. Turn their character token upside down {{i|(this shows they are now evil.)}}, then place the **INFECTED** reminder token in the center of the Grimoire."],"iconBy":"le_nuberto","customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"If you want to use the older version of the Enfekthyte, which was a virus that started alone and spread to create it''s own Legional army, use this JSON.\n\nWhile setting up the game, remove all Minion tokens and add Townsfolk or Outsider tokens.\n\nDuring the night, whilst the **STERILE** reminder is not on the Grimoire, if a player chooses to use their ability on the Enfekthyte, immediately replace their character token with the Enfekthyte''s character token, show them the **YOU ARE** info token, then the Enfekthyte''s character token, and give a thumbs down. If you believe that enough of the players are the Enfekthyte, put in the **STERILE** reminder token.\n\nDuring the day, whilst the **STERILE** reminder is not on the Grimoire, if a player chooses to use their ability on the Enfekthyte, nominates them, or an Enfekthyte nominates them, mark them with the **INFECTED** reminder. If you believe that enough of the players are to be the Enfekthyte, put in the **STERILE** reminder token.\n\nAt dusk, replace the character tokens of players marked with the **INFECTED** reminder with the Enfekthyte''s character token. Wake each new Enfekthyte, show them the **YOU ARE** info token, then the Enfekthyte''s character token, and give a thumbs down. Put them to sleep.\n\nEach night except the first, you may decide that 0 - 2 players die.\n\nIf a vote has just been tallied, but no good players voted, the executed player does not die, declare that the player was executed but remains alive {{i|(do not say why.)}}\n\n**Enfekthyte █** (Demon)\nEach night*, 2 players might die. Executions don''t kill if only evil voted. This spreads by pointing whilst most players aren''t evil. [No minions]\n\n**Other nights:** Choose 0-2 players, those player(s) dies.\n**Reminders:** Good Voted, Infected, Infected, Infected, Infected, Infected, Infected, Infected, Infected, Infected, Infected, Infected, Sterile, Dead, Dead\n**Setup:** yes\n**Credit:** Ability: @legitch. Image: @le_nuberto\n\n**Jinxes:**\nClockmaker: Only 1 jinxed character can be in play.\nDamsel: The Enfekthyte registers as a Minion to the Damsel.\nEngineer: The Enfekthyte and the Engineer can not both be in play at the start of the game. If the Engineer creates the Enfekthyte, all evil players and some to most other players become evil the Enfekthyte.\nHatter: If the Hatter dies and the Enfekthyte is in play, nothing happens. If the Hatter dies and an evil player chooses the Enfekthyte, all current evil players and some to most other players become evil the Enfekthyte.\nInvestigator: Only 1 jinxed character can be in play.\nMagician: Only 1 jinxed character can be in play.\nMinstrel: Only 1 jinxed character can be in play.\nPoppy Grower: Only 1 jinxed character can be in play.\nPreacher: The Enfekthyte registers as a Minion to the Preacher if it isn''t the last remaining evil player with their ability.\nSummoner: If the Summoner create the Enfekthyte, all evil players become evil the Enfekthyte.\nTown Crier: The Enfekthyte registers as a Minion to the Town Crier.\nZealot: The Zealot might register as evil to the Enfekthyte''s ability.\nBall o'' Death: The Ball o'' Death kills any Enfekthyte''s they choose.\nPrognosticator: The Enfekthyte registers as a Minion to the Prognosticator.\nEyepod: The Enfekthyte registers as a Minion to the Eyepod.\nSauelsuesor: The Enfekthyte registers as a Minion to the Sauelsuesor.\nPorcher: If the Enfekthyte is in play and the Porcher dies, nothing happens.\nPrankster: Only 1 jinxed character can be in play.\nShinobi: Only the 1st few Enfekthytes register as Minions to the Shinobi.\nCandlemaker: The Enfekthyte registers as a Minion to the Candlemaker.\nBoxer: The Boxer cannot be infected by choosing a player, but can be infected by a player choosing them.\nDraper: Only the 1st few Enfekthytes register as Minions to the Draper.\nOrnithologist: If the Ornithologist is in play, the Enfekthyte does not remove any Minions, but instead also makes them Enfekthytes. They can think they are any Minion or Demon, but they cannot infect anyone during this. At any time, the Ornithologist might die.\nRat-Catcher: The Enfekthyte registers as a Minion to the Rat-Catcher.\nUnicorn: The Enfekthyte registers as a Minion to the Unicorn.\nVicar: The Vicar assumes there is a normal amount of Minions with the Enfekthyte in-play."}],"firstNight":0,"otherNight":41.61,"reminders":["Dead","Infected"],"setup":true,"otherNightReminder":"If a player with a marked character executed a good player today: swap the Enfekthyte and their character token. Wake each player to inform them of their new role, and show the new Enfekthyte the thumbs down evil signal. The Enfekthyte points to a player. That player dies.","art":"art/enfekthyte.png","jsonId":"enfekthyte_scp_fragmented_veil","curata":false}','scp-fragmented-veil/enfekthyte','published',datetime('now'),datetime('now')),
('haedlaite','Haedlaite','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"haedlaite","name":"Haedlaite","team":"demon","ability":"Each night*, even if dead, choose a player: they die. If a Demon died today, you don''t wake tonight. [Another Minion is this]","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-745 are bipedal predators that mimic the headlights of a car when they hunt. They''re known for their behaviour to pair up in packs of two.","summaryBullets":["The Haedlaite will continue to act and wake when dead, which only concerns the 1st Haedlaite that dies.","Both Haedlaite''s need to die for the good team to naturally win.","Whenever a Haedlaite is executed and dies, both Haedlaites will mourn the death and won''t wake tonight."],"howToRun":["While setting up the game, before putting character tokens in the bag, remove any one Minion''s character tokens and add another Haedlaite character token.","Each night except the first, wake any Haedlaite, even if they''re dead. They point at any player. That player {{i|dies}} - mark them with the **DEAD** reminder. Put that Haedlaite to sleep. Repeat for the other Haedlaite to act.","If the Haedlaite dies during the day, mark them with the **MOURNING** reminder. That night, if an Haedlaite would wake, they instead don''t, then the **MOURNING** reminder token is removed."],"iconBy":"le_nuberto","jinxes":[{"name":"Engineer","align":"good","text":"If the Haedlaite is put into play by the Engineer, a Minion becomes the Haedlaite. If the Haedlaite is put out of play, one of them becomes an out-of-play Minion.","id":"engineer"},{"name":"Hatter","align":"good","text":"If the Haedlaite is put into play by the Hatter, a Minion becomes the Haedlaite. If the Hatter dies, the Haedlaite can choose to be Minion if another the Haedlaite exists, which forces the other the Haedlaite to become another Demon.","id":"hatter"},{"name":"Pit-Hag","align":"evil","text":"If the Pit-Hag creates the Haedlaite, another evil player might become the Haedlaite.","id":"pithag"},{"name":"Scarlet Woman","align":"evil","text":"The Scarlet Woman''s ability is replaced with: \"Haedlaites do not mourn and will still wake when another Haedlaite dies.\"","id":"scarletwoman"},{"name":"Summoner","align":"evil","text":"If the Summoner creates the Haedlaite, they also become a Haedlaite.","id":"summoner"},{"name":"Fencer","align":"good","text":"If the Haedlaite kills the Fencer, the Haedlaite dies and can''t wake.","id":"fencer_darkartists_stuff"}],"firstNight":0,"otherNight":35.745,"reminders":["Mourning","Dead","Dead"],"setup":true,"special":[{"name":"bag-duplicate","type":"selection"}],"otherNightReminder":"The Haedlaite points to a player. That player dies.","art":"art/haedlaite.png","jsonId":"haedlaite_scp_fragmented_veil","curata":false}','scp-fragmented-veil/haedlaite','published',datetime('now'),datetime('now')),
('big-red-dog','"Big Red Dog"','demon','katsitsanoron',NULL,'','SCP Fragmented Veil','{"slug":"big-red-dog","name":"\"Big Red Dog\"","team":"demon","ability":"Each night* choose a player: they die. You learn the character, have the ability of & might register as them until the next dawn.","creator":"katsitsanoron","appearsIn":"SCP Fragmented Veil","lede":"SCP-939 are endothermic skinless predator that lures others into death by mimicking their victim''s pleas of help.","summaryBullets":["When the \"Big Red Dog\" successfully kills a player, they learn their character, gain their ability, and might register as they would until the next dawn.","This will still occur if the \"Big Red Dog\" successfully kills a Minion or even another Demon {{i|(somehow)}}, but not an Outsider.","The \"Big Red Dog\" will not absorb these traits if the victim wasn''t successfully killed.","The \"Big Red Dog\" effectively can use their victim''s ability twice if they act/wake after the \"Big Red Dog\" on the night order sheet - the first time the same night, the second time the next one.","Whilst the \"Big Red Dog\" can misregister as a different character, they cannot misregister their alignment, and will always normally show as evil."],"howToRun":["Each night except the first, wake the \"Big Red Dog\". They point at any player. That player {{i|dies}} - mark them with the **DEAD** reminder, and if both successful and the victim is not an Outsider, show their character token and mark them with the **STOLEN** reminder. the \"Big Red Dog\" now has the victim’s ability {{i|(until the dawn after the upcoming one)}}, and will wake at night when their character would normally wake {{i|(you can now use the dead character’s reminders for the \"Big Red Dog\")}}. To avoid confusion between the ability they steal from their latest victim, their victim prior, and their own killing ability, show them the character token of the ability they are using when waking them up for all cases. Put the \"Big Red Dog\" to sleep.","At dawn, remove the **STOLEN** reminder on any player without the **DEAD** reminder before announcing who has died and removing the **DEAD** reminders from the \"Big Red Dog\"''s victim.","Each time the \"Big Red Dog\" is targeted by an ability that detects or affects the character type of the victim whilst they are marked with the **STOLEN** reminder, choose what character the \"Big Red Dog\" registers as based off the latest victim. Do whatever is appropriate, such as showing a certain character token, nodding, giving finger signals, or allowing an ability to work that would normally only affect certain types of characters."],"examples":["During the second night, the \"Big Red Dog\" attacks and successfully kills the Artist. They are shown the Artist''s character token to indicate that this is the character they killed. The upcoming day, the \"Big Red Dog\" asks the Storyteller for a private meeting to learn the answer to their yes/no question.","The King learns that there is a living Choirboy. In reality, the Choirboy was the latest victim of the \"Big Red Dog\", who is currently registering to the King as them.","The \"Big Red Dog\" attacks and successfully kills the Fisherman. The \"Big Red Dog\" forgets to use the Fisherman''s advice the upcoming day during the commotion. The night after, the \"Big Red Dog\" attacks but fails to kill someone. The day after, the \"Big Red Dog\" requests the Storyteller for a private meeting, but is denied as they no longer had the Fisherman''s ability since dawn."],"iconBy":"le_nuberto","jinxes":[{"name":"Cult Leader","align":"good","text":"If the \"Big Red Dog\" gains the Cult Leader ability, they can''t turn good due to it.","id":"cultleader"},{"name":"Drunk","align":"good","text":"If the \"Big Red Dog\" gains the Drunk ability, they instead think they have the ability the Drunk had.","id":"drunk"},{"name":"Goon","align":"good","text":"If the \"Big Red Dog\" gains the Goon ability, they can''t turn good due to it.","id":"goon"},{"name":"Ogre","align":"good","text":"If the \"Big Red Dog\" gains the Ogre ability, they can''t turn good due to it.","id":"ogre"},{"name":"Politician","align":"good","text":"If the \"Big Red Dog\" gains the Politician ability, they can''t turn good due to it.","id":"politician"},{"name":"Cardinal","align":"good","text":"If the \"Big Red Dog\" gains the Cardinal ability, they can''t turn good due to it.","id":"cardinal_the_bootleggers_anthology"},{"name":"Sleepwalker","align":"good","text":"If the \"Big Red Dog\" gains the Sleepwalker ability, they instead think they have the ability the Drunk had.","id":"sleepwalker_the_bootleggers_anthology"},{"name":"Shoe-In","align":"good","text":"If the \"Big Red Dog\" gains the Shoe-In ability, they can''t turn good due to it.","slug":"shoe-in"},{"name":"C-Insurgency","align":"good","text":"If the \"Big Red Dog\" gains the C-Insurgency ability, they can''t turn good due to it.","slug":"c-insurgency"}],"customBoxes":[{"title":"Credit","content":"Ability: @katsitsanoron. Image: @le_nuberto. Help: @legitch"},{"title":"In the almanac JSON","content":"**Ability:** Each night* choose a player: they die. You learn the character, have the ability of & might register as them (if not an Outsider) until the next dawn."}],"firstNight":0,"otherNight":35.939,"reminders":["Stolen","Stolen","Dead"],"setup":false,"otherNightReminder":"The \"Big Red Dog\" points to a player. That player dies. If that player isn''t protected: Show the character token of that player and place the Stolen marker by that player.","art":"art/big-red-dog.png","jsonId":"bigreddog_scp_fragmented_veil","curata":false}','scp-fragmented-veil/big-red-dog','published',datetime('now'),datetime('now')),
('untisaleep','Untisaleep','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"untisaleep","name":"Untisaleep","team":"demon","ability":"Each night*, choose a player: they die. If all living or no good players woke tonight & a good player is executed, evil wins.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-966 are invisible humanoid predators with sharp claws that can emit bursts of waves which permanently inhibit sleep, deteriorating one''s mind and soul.","summaryBullets":["Sleep too little, or sleep too much, and this Demon holds the world in it''s clutch.","Evil players do not register to the win-condition activation of this ability, no matter what.","If the win-condition aspect of this ability activated, but a good player was failed to be executed the next day, it is not prematurely activated for further days unless the same conditions are met."],"howToRun":["Each night except the first, wake the Untisaleep. They point at any player. That player {{i|dies}} - mark them with the **DEAD** reminder. Put the Untisaleep to sleep.","Each dawn, evaluate which players woke tonight. If all of the living good players woke tonight, or no good player woke tonight, put the **SLEEPLESS** reminder token on the Untisaleep. If a good player is executed whilst the **SLEEPLESS** reminder token is present, declare that the game ends and evil wins.","Each dusk, remove the **SLEEPLESS** reminder token if its present."],"iconBy":"le_nuberto","firstNight":0,"otherNight":35.966,"reminders":["Sleepless","Dead"],"setup":false,"otherNightReminder":"The Untisaleep points to a player. That player dies.","art":"art/untisaleep.png","jsonId":"untisaleep_scp_fragmented_veil","curata":false}','scp-fragmented-veil/untisaleep','published',datetime('now'),datetime('now'));
